"""Validate a stable release tag and extract its changelog notes.

Generated by aurora@aurora-smart-home (ha-integration-dev skill)
https://github.com/tonylofgren/aurora-smart-home
"""

import json
import os
import re
from pathlib import Path


def main() -> None:
    """Fail before publication if release metadata disagrees."""
    tag = os.environ["RELEASE_TAG"]
    if not re.fullmatch(r"v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", tag):
        raise SystemExit("Expected a stable semantic version tag: vMAJOR.MINOR.PATCH")
    version = tag[1:]
    manifest = json.loads(
        Path("custom_components/ha_flightseats/manifest.json").read_text()
    )
    if manifest["version"] != version:
        raise SystemExit("Tag version does not match manifest.json")
    changelog = Path("CHANGELOG.md").read_text()
    section = re.search(
        rf"^## {re.escape(version)}(?: \([^\n]*\))?\n(.*?)(?=^## |\Z)",
        changelog,
        re.MULTILINE | re.DOTALL,
    )
    if section is None or not section[1].strip():
        raise SystemExit("Missing versioned changelog notes")
    if "unreleased" in section[0].splitlines()[0].lower():
        raise SystemExit("Changelog version is still marked unreleased")
    Path("release-notes.md").write_text(section[1].strip() + "\n")
    print(f"Validated {tag}; release notes written to release-notes.md")


if __name__ == "__main__":
    main()
